import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
import Peer from 'https://esm.sh/peerjs@1.5.4';

const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a5a4d5');
scene.fog = new THREE.FogExp2('#a5a4d5', 0.011);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 180);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

scene.add(new THREE.HemisphereLight('#e5e5ff', '#55527d', 2.2));
const sun = new THREE.DirectionalLight('#fff0d4', 3.2);
sun.position.set(-12, 24, 10); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -40; sun.shadow.camera.right = 40; sun.shadow.camera.top = 40; sun.shadow.camera.bottom = -40;
scene.add(sun);
const fill = new THREE.PointLight('#8cf5e5', 42, 42); fill.position.set(1, 8, -15); scene.add(fill);

const mat = (color, roughness = 0.7, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const materials = {
  lavender: mat('#b3b8fa', .48), mint: mat('#8fe8d5', .45), pink: mat('#f3a5cc', .48), cream: mat('#ffe3a9', .5),
  dark: mat('#303559', .75), trim: mat('#dedfff', .35), glass: new THREE.MeshStandardMaterial({ color: '#b8fff0', roughness: .2, metalness: .2, emissive: '#4ddbc5', emissiveIntensity: .45 })
};
const platforms = [];
function platform(x, y, z, w, d, color, options = {}) {
  const h = options.h || .75;
  const group = new THREE.Group(); group.position.set(x, y, z); scene.add(group);
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color, .57, .04));
  body.castShadow = true; body.receiveShadow = true; group.add(body);
  const top = new THREE.Mesh(new THREE.BoxGeometry(w - .16, .08, d - .16), mat(options.top || '#e2e4ff', .62));
  top.position.y = h / 2 + .025; top.receiveShadow = true; group.add(top);
  const edge = new THREE.Mesh(new THREE.BoxGeometry(w + .06, .12, d + .06), mat(options.edge || '#828dcf', .38, .1));
  edge.position.y = -h / 2 + .1; group.add(edge);
  if (options.glow) {
    const strip = new THREE.Mesh(new THREE.BoxGeometry(w * .68, .035, .09), new THREE.MeshBasicMaterial({ color: options.glow }));
    strip.position.set(0, -h / 2 + .16, d / 2 + .04); group.add(strip);
  }
  platforms.push({ x, z, y: y + h / 2 + .08, w: w - .15, d: d - .15 });
  return group;
}

// A floating, pastel obstacle course under the sunset clouds.
platform(0, 0, 9, 13, 16, '#8285c7', { top: '#c6c8ff', edge: '#666caa', glow: '#98f4e3' });
platform(-4, .9, -2, 5.2, 5.2, '#91c5d6', { top: '#d3f4ed', edge: '#568ca6', glow: '#9af4df' });
platform(3.1, 1.8, -9.1, 4.6, 4.7, '#c19bd4', { top: '#f5d8ed', edge: '#8a6cae', glow: '#ffd49b' });
platform(-2.2, 2.8, -16.3, 4.8, 4.4, '#dfad9f', { top: '#ffe0c5', edge: '#aa777b', glow: '#ffcb99' });
platform(3.5, 3.8, -23.2, 4.6, 4.7, '#92bca9', { top: '#d2f3d9', edge: '#5d8e86', glow: '#a0ffe2' });
platform(0, 4.8, -31, 10, 10, '#7b8cc2', { top: '#d5dcff', edge: '#536390', glow: '#a5ffdf' });

// Low-poly clouds and distant floating shards give the sky a sense of scale.
const cloudMat = new THREE.MeshStandardMaterial({ color: '#ecebff', roughness: 1, transparent: true, opacity: .8 });
for (let i = 0; i < 22; i++) {
  const x = (Math.random() - .5) * 90, z = -45 + Math.random() * 68, y = 8 + Math.random() * 19;
  const cloud = new THREE.Group(); cloud.position.set(x, y, z); scene.add(cloud);
  for (let j = 0; j < 4; j++) {
    const puff = new THREE.Mesh(new THREE.IcosahedronGeometry(1.6 + Math.random() * 1.8, 1), cloudMat);
    puff.position.set((j - 1.5) * 1.8, Math.random() * .5, Math.random() * .8); puff.scale.y = .55; cloud.add(puff);
  }
}
for (let i = 0; i < 32; i++) {
  const shard = new THREE.Mesh(new THREE.OctahedronGeometry(.4 + Math.random() * .8), mat(i % 2 ? '#f6c6d9' : '#c9d4ff', .45));
  shard.position.set((Math.random() - .5) * 65, 3 + Math.random() * 20, -35 + Math.random() * 50); shard.rotation.set(Math.random(), Math.random(), Math.random()); scene.add(shard);
}

// Dotted luminous stepping stones subtly trace the route.
for (let i = 0; i < 18; i++) {
  const t = i / 17, z = 8 - t * 38, x = Math.sin(t * Math.PI * 4) * 2.1;
  const bead = new THREE.Mesh(new THREE.SphereGeometry(.055, 8, 8), new THREE.MeshBasicMaterial({ color: '#d7fff2', transparent: true, opacity: .6 }));
  bead.position.set(x, 1.25 + t * 4.8, z); scene.add(bead);
}

function makeAvatar(color = '#f5a982') {
  const root = new THREE.Group();
  const bodyMat = mat(color, .48), pantsMat = mat('#454a7b', .62), whiteMat = mat('#fff0d8', .38), shoeMat = mat('#293453', .62);
  const body = new THREE.Mesh(new THREE.BoxGeometry(.78, .8, .42), bodyMat); body.position.y = .99; body.castShadow = true; root.add(body);
  const head = new THREE.Mesh(new THREE.BoxGeometry(.62, .62, .61), whiteMat); head.position.y = 1.72; head.castShadow = true; root.add(head);
  const hair = new THREE.Mesh(new THREE.BoxGeometry(.68, .2, .66), mat('#443c65', .8)); hair.position.set(0, 2.08, -.015); root.add(hair);
  const eyeMat = new THREE.MeshBasicMaterial({ color: '#323753' });
  for (const x of [-.14, .14]) { const eye = new THREE.Mesh(new THREE.BoxGeometry(.055, .065, .018), eyeMat); eye.position.set(x, 1.78, .315); root.add(eye); }
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.BoxGeometry(.3, .61, .34), pantsMat); leg.position.set(side * .2, .31, 0); leg.castShadow = true; root.add(leg);
    const shoe = new THREE.Mesh(new THREE.BoxGeometry(.34, .18, .47), shoeMat); shoe.position.set(side * .2, .07, .045); root.add(shoe);
    const arm = new THREE.Mesh(new THREE.BoxGeometry(.24, .69, .3), bodyMat); arm.position.set(side * .52, .98, 0); arm.castShadow = true; root.add(arm);
  }
  const backpack = new THREE.Mesh(new THREE.BoxGeometry(.43, .5, .2), mat('#75d9cf', .4)); backpack.position.set(0, 1.05, -.29); root.add(backpack);
  root.userData.legs = root.children.filter((_, i) => i === 4 || i === 6);
  return root;
}
const player = { group: makeAvatar(), pos: new THREE.Vector3(0, .08, 12), vel: new THREE.Vector3(), grounded: true, checkpoint: new THREE.Vector3(0, .08, 12), stars: 0, score: 0 };
scene.add(player.group); player.group.position.copy(player.pos);
let avatarBob = 0;

// The chaser is a real image texture on a billboard. Its movement is intentionally
// unconstrained by the platform collision system, so it slips straight through walls.
function makeIdTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 256;
  const g = c.getContext('2d');
  const glow = g.createRadialGradient(128, 128, 54, 128, 128, 128);
  glow.addColorStop(0, '#ffb1b8'); glow.addColorStop(.58, '#fa6e95'); glow.addColorStop(1, '#e34982');
  g.fillStyle = glow; g.beginPath(); g.arc(128, 128, 123, 0, Math.PI * 2); g.fill();
  g.strokeStyle = '#fff0e8'; g.lineWidth = 8; g.stroke();
  g.fillStyle = '#fff5e9'; g.beginPath(); g.ellipse(128, 134, 74, 82, 0, 0, Math.PI * 2); g.fill();
  g.fillStyle = '#483450';
  g.beginPath(); g.ellipse(100, 122, 11, 20, -.1, 0, Math.PI * 2); g.fill();
  g.beginPath(); g.ellipse(156, 122, 11, 20, .1, 0, Math.PI * 2); g.fill();
  g.strokeStyle = '#68455c'; g.lineWidth = 9; g.lineCap = 'round';
  g.beginPath(); g.moveTo(98, 177); g.quadraticCurveTo(128, 151, 158, 177); g.stroke();
  g.fillStyle = '#fff8e9'; g.font = 'bold 20px sans-serif'; g.textAlign = 'center'; g.fillText('ID', 128, 238);
  const texture = new THREE.CanvasTexture(c); texture.colorSpace = THREE.SRGBColorSpace; return texture;
}
const idGroup = new THREE.Group(); scene.add(idGroup);
const idSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: makeIdTexture(), transparent: true, depthWrite: false }));
idSprite.scale.set(2.35, 2.35, 1); idGroup.add(idSprite);
const idHalo = new THREE.Mesh(new THREE.TorusGeometry(1.35, .035, 8, 48), new THREE.MeshBasicMaterial({ color: '#ff91ae', transparent: true, opacity: .7 }));
idHalo.rotation.x = Math.PI / 2; idGroup.add(idHalo);
const idLight = new THREE.PointLight('#ff648f', 3.2, 8); idGroup.add(idLight);
idGroup.position.set(1.8, 2.25, 23);

const starShape = new THREE.Shape();
for (let i = 0; i < 10; i++) {
  const r = i % 2 === 0 ? .43 : .2, a = Math.PI / 2 + i * Math.PI / 5;
  const x = Math.cos(a) * r, y = Math.sin(a) * r;
  i === 0 ? starShape.moveTo(x, y) : starShape.lineTo(x, y);
}
starShape.closePath();
const starGeo = new THREE.ExtrudeGeometry(starShape, { depth: .1, bevelEnabled: true, bevelThickness: .06, bevelSize: .04, bevelSegments: 2 });
const stars = [];
const starPoints = [
  [-2.4, 1.8, 2.1], [-4, 2.3, -2.1], [3.1, 3.2, -8.8], [4.1, 3.5, -10.3],
  [-2.4, 4.1, -16.3], [-.5, 4.2, -15.1], [3.4, 5.1, -23.2], [0, 6.1, -31]
];
for (const [x, y, z] of starPoints) {
  const group = new THREE.Group(); const star = new THREE.Mesh(starGeo, new THREE.MeshStandardMaterial({ color: '#ffdc91', emissive: '#ffb94e', emissiveIntensity: 1.4, roughness: .28, metalness: .2 }));
  star.castShadow = true; group.add(star);
  const halo = new THREE.Mesh(new THREE.TorusGeometry(.62, .018, 6, 32), new THREE.MeshBasicMaterial({ color: '#ffedb4', transparent: true, opacity: .48 })); halo.rotation.x = Math.PI / 2; group.add(halo);
  const light = new THREE.PointLight('#ffc96c', 1.4, 4); group.add(light);
  group.position.set(x, y, z); scene.add(group); stars.push({ group, collected: false });
}

// The finish beacon is visible from spawn and pulses as the player approaches.
const goal = new THREE.Group(); goal.position.set(0, 6.05, -31); scene.add(goal);
const beacon = new THREE.Mesh(new THREE.CylinderGeometry(.13, .2, 2.9, 8), materials.glass); beacon.position.y = 1.55; beacon.castShadow = true; goal.add(beacon);
const beaconTop = new THREE.Mesh(new THREE.OctahedronGeometry(.55, 0), new THREE.MeshBasicMaterial({ color: '#b5fff0' })); beaconTop.position.y = 3.25; goal.add(beaconTop);
const beaconRing = new THREE.Mesh(new THREE.TorusGeometry(1.15, .055, 9, 56), new THREE.MeshBasicMaterial({ color: '#a3ffea' })); beaconRing.position.y = 2.1; beaconRing.rotation.x = Math.PI / 2; goal.add(beaconRing);
const goalLight = new THREE.PointLight('#9cf6dd', 11, 15); goalLight.position.y = 2.5; goal.add(goalLight);

const keys = new Set();
let jumpQueued = false, audioOn = false, audioContext;
addEventListener('keydown', e => {
  const k = e.key.toLowerCase();
  if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
  keys.add(k);
  if (k === ' ' || k === 'w' || k === 'arrowup') jumpQueued = true;
});
addEventListener('keyup', e => keys.delete(e.key.toLowerCase()));
for (const button of document.querySelectorAll('[data-key]')) {
  const k = button.dataset.key;
  const down = e => { e.preventDefault(); button.setPointerCapture?.(e.pointerId); if (k === 'space') jumpQueued = true; else { keys.add(k); if (k === 'w') jumpQueued = true; } };
  const up = e => { e.preventDefault(); if (k !== 'space') keys.delete(k); };
  button.addEventListener('pointerdown', down); button.addEventListener('pointerup', up); button.addEventListener('pointercancel', up); button.addEventListener('lostpointercapture', up);
}

const $ = s => document.querySelector(s);
const toast = (text) => { const el = $('#toast'); el.textContent = text; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2200); };
function playTone(freq = 700, duration = .12) {
  if (!audioOn) return;
  try { audioContext ||= new AudioContext(); const osc = audioContext.createOscillator(), gain = audioContext.createGain(); osc.frequency.value = freq; osc.type = 'sine'; gain.gain.setValueAtTime(.055, audioContext.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + duration); osc.connect(gain); gain.connect(audioContext.destination); osc.start(); osc.stop(audioContext.currentTime + duration); } catch {}
}
$('#sound-btn').addEventListener('click', () => { audioOn = !audioOn; $('#sound-btn').textContent = audioOn ? '♫' : '♪'; toast(audioOn ? 'SOUND ON' : 'SOUND OFF'); playTone(680); });
$('#help-btn').addEventListener('click', () => $('#help-modal').classList.add('open'));
$('#help-close').addEventListener('click', () => $('#help-modal').classList.remove('open'));
$('#got-it').addEventListener('click', () => $('#help-modal').classList.remove('open'));
$('#join-btn').addEventListener('click', () => $('#join-modal').classList.add('open'));
$('#modal-close').addEventListener('click', () => $('#join-modal').classList.remove('open'));
$('#join-modal').addEventListener('click', e => { if (e.target === $('#join-modal')) $('#join-modal').classList.remove('open'); });
$('#help-modal').addEventListener('click', e => { if (e.target === $('#help-modal')) $('#help-modal').classList.remove('open'); });
$('#copy-room').addEventListener('click', async () => { try { await navigator.clipboard.writeText($('#room-code').textContent); toast('ROOM CODE COPIED'); } catch { toast(`ROOM: ${$('#room-code').textContent}`); } });

let checkpointIndex = 0, caughtTimer = 0, win = false, distance = 0, gameTime = 0;
function setCheckpoint(index) {
  if (index <= checkpointIndex) return;
  checkpointIndex = index; player.checkpoint.set(player.pos.x, player.pos.y, player.pos.z);
  toast('CHECKPOINT SAVED'); playTone(820, .16);
}
function respawn(message) {
  player.pos.copy(player.checkpoint); player.vel.set(0, 0, 0); player.grounded = true;
  idGroup.position.set(player.pos.x + (Math.random() - .5) * 2, player.pos.y + 2.3, player.pos.z + 13);
  caughtTimer = 1.2; $('#danger-banner').classList.remove('show');
  toast(message); playTone(180, .28);
}

// Multiplayer is peer-to-peer through PeerJS; a room host relays tiny avatar snapshots.
let peer = null, isHost = false, room = 'SKY-01', myPeerId = null, sendClock = 0;
const connections = new Map(), remotePlayers = new Map();
const avatarColors = ['#9de9d7', '#d2a5ee', '#f4c778', '#95b9f4', '#f39eb5'];
function setRoomUi(label, code, status) { $('#session-label').textContent = label; $('#room-code').textContent = code; $('#room-status').textContent = status; }
function makeRemote(id, data = {}) {
  if (remotePlayers.has(id)) return remotePlayers.get(id);
  const color = data.color || avatarColors[remotePlayers.size % avatarColors.length];
  const group = makeAvatar(color); scene.add(group);
  const tagCanvas = document.createElement('canvas'); tagCanvas.width = 256; tagCanvas.height = 64;
  const ctx = tagCanvas.getContext('2d'); ctx.fillStyle = '#171832'; ctx.globalAlpha = .8; ctx.roundRect(8, 8, 240, 46, 18); ctx.fill();
  ctx.globalAlpha = 1; ctx.fillStyle = '#fff'; ctx.font = 'bold 20px sans-serif'; ctx.textAlign = 'center'; ctx.fillText((data.name || `PLAYER ${remotePlayers.size + 2}`).slice(0, 14), 128, 38);
  const label = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(tagCanvas), transparent: true, depthWrite: false })); label.scale.set(2, .5, 1); label.position.y = 2.8; group.add(label);
  const remote = { group, target: new THREE.Vector3(), color }; remotePlayers.set(id, remote); updatePlayerCount(); return remote;
}
function removeRemote(id) { const remote = remotePlayers.get(id); if (!remote) return; scene.remove(remote.group); remotePlayers.delete(id); updatePlayerCount(); }
function updatePlayerCount() { $('#player-count').textContent = String(remotePlayers.size + 1); }
function applyRemote(id, data) {
  if (!data || data.type !== 'state' || id === myPeerId || !data.pos) return;
  const remote = makeRemote(id, data); remote.target.set(data.pos.x, data.pos.y, data.pos.z); remote.group.rotation.y = data.yaw || 0;
}
function broadcastState() {
  const payload = { type: 'state', pos: { x: player.pos.x, y: player.pos.y, z: player.pos.z }, yaw: player.group.rotation.y, color: '#f5a982', name: 'SKY RUNNER' };
  for (const [id, conn] of connections) if (conn.open) { try { conn.send(payload); } catch {} }
}
function acceptConnection(conn) {
  connections.set(conn.peer, conn);
  conn.on('data', data => {
    applyRemote(conn.peer, data);
    if (isHost && data?.type === 'state') for (const [otherId, other] of connections) if (otherId !== conn.peer && other.open) { try { other.send({ ...data, id: conn.peer }); } catch {} }
  });
  conn.on('close', () => { connections.delete(conn.peer); removeRemote(conn.peer); });
  conn.on('error', () => { connections.delete(conn.peer); removeRemote(conn.peer); });
  conn.on('open', () => { toast('PLAYER SPAWNED IN'); if (isHost) broadcastState(); });
}
function closeNetwork() {
  connections.forEach(c => { try { c.close(); } catch {} }); connections.clear();
  remotePlayers.forEach((_, id) => removeRemote(id));
  if (peer) { try { peer.destroy(); } catch {} peer = null; }
  isHost = false; myPeerId = null; updatePlayerCount();
}
function peerError(err) {
  const msg = err?.type === 'peer-unavailable' ? 'ROOM NOT FOUND — CHECK THE CODE' : err?.type === 'unavailable-id' ? 'ROOM CODE IS ALREADY HOSTED' : 'CONNECTION ISSUE — TRY AGAIN';
  toast(msg); $('#room-status').textContent = 'OFFLINE';
}
function hostRoom(code) {
  closeNetwork(); room = code.toUpperCase(); const id = `skybound-${room.toLowerCase().replace(/[^a-z0-9-]/g, '')}`;
  if (id.length < 10) { toast('PLEASE ENTER A ROOM CODE'); return; }
  peer = new Peer(id, { host: '0.peerjs.com', port: 443, path: '/', secure: true, debug: 1 });
  isHost = true; setRoomUi('HOSTING WORLD', room, 'CONNECTING');
  peer.on('open', id => { myPeerId = id; setRoomUi('HOSTING WORLD', room, 'ONLINE'); toast(`WORLD OPEN — SHARE ${room}`); });
  peer.on('connection', acceptConnection); peer.on('error', peerError);
  peer.on('disconnected', () => { $('#room-status').textContent = 'RETRYING'; try { peer.reconnect(); } catch {} });
}
function joinRoom(code) {
  closeNetwork(); room = code.toUpperCase(); const id = `skybound-${room.toLowerCase().replace(/[^a-z0-9-]/g, '')}`;
  if (id.length < 10) { toast('PLEASE ENTER A ROOM CODE'); return; }
  peer = new Peer(undefined, { host: '0.peerjs.com', port: 443, path: '/', secure: true, debug: 1 });
  setRoomUi('JOINING WORLD', room, 'CONNECTING');
  peer.on('open', ownId => {
    myPeerId = ownId; const conn = peer.connect(id, { reliable: true }); acceptConnection(conn);
    conn.on('open', () => { isHost = false; setRoomUi('CREW SESSION', room, 'ONLINE'); toast('YOU DROPPED INTO THE WORLD'); broadcastState(); });
  });
  peer.on('error', peerError); peer.on('disconnected', () => { $('#room-status').textContent = 'RETRYING'; try { peer.reconnect(); } catch {} });
}
$('#host-btn').addEventListener('click', () => { $('#room-input').value = $('#room-code').textContent; $('#join-modal').classList.add('open'); $('#connect-btn').textContent = 'HOST WORLD ↗'; $('#connect-btn').dataset.mode = 'host'; });
$('#join-btn').addEventListener('click', () => { $('#join-modal').classList.add('open'); $('#connect-btn').textContent = 'JOIN WORLD ↗'; $('#connect-btn').dataset.mode = 'join'; });
$('#connect-btn').addEventListener('click', () => {
  const code = $('#room-input').value.trim().toUpperCase().replace(/\s+/g, '-');
  $('#join-modal').classList.remove('open'); $('#room-input').value = code;
  if ($('#connect-btn').dataset.mode === 'host') hostRoom(code); else joinRoom(code);
});
$('#room-input').addEventListener('keydown', e => { if (e.key === 'Enter') $('#connect-btn').click(); });

// Distant pastel architecture and a soft sunset disc frame the playable islands.
const sunset = new THREE.Mesh(new THREE.CircleGeometry(7, 48), new THREE.MeshBasicMaterial({ color: '#ffd9bb', transparent: true, opacity: .8 }));
sunset.position.set(-19, 20, -48); sunset.lookAt(camera.position); scene.add(sunset);
for (let i = 0; i < 13; i++) {
  const h = 3 + Math.random() * 9, x = -34 + i * 5.5, z = -45 - Math.random() * 15;
  const tower = new THREE.Mesh(new THREE.BoxGeometry(1.1 + Math.random() * 2, h, 1 + Math.random() * 2), mat(i % 2 ? '#a9add9' : '#c4b8db', .9));
  tower.position.set(x, h / 2 - 1, z); scene.add(tower);
  const windowLine = new THREE.Mesh(new THREE.BoxGeometry(.035, h * .62, .05), new THREE.MeshBasicMaterial({ color: '#fff0d4', transparent: true, opacity: .6 }));
  windowLine.position.set(x + .22, h * .46 - 1, z + .55); scene.add(windowLine);
}

const clock = new THREE.Clock();
function updatePlayer(dt) {
  const forward = keys.has('w') || keys.has('arrowup'), back = keys.has('s') || keys.has('arrowdown');
  const left = keys.has('a') || keys.has('arrowleft'), right = keys.has('d') || keys.has('arrowright');
  let dx = (right ? 1 : 0) - (left ? 1 : 0), dz = (back ? 1 : 0) - (forward ? 1 : 0);
  const length = Math.hypot(dx, dz) || 1; dx /= length; dz /= length;
  const speed = 5.6;
  player.vel.x = THREE.MathUtils.damp(player.vel.x, dx * speed, dx || dz ? 11 : 13, dt);
  player.vel.z = THREE.MathUtils.damp(player.vel.z, dz * speed, dx || dz ? 11 : 13, dt);
  player.pos.x += player.vel.x * dt; player.pos.z += player.vel.z * dt;
  const oldY = player.pos.y;
  if (jumpQueued && player.grounded) { player.vel.y = 9.1; player.grounded = false; playTone(420, .08); }
  jumpQueued = false;
  if (!player.grounded) { player.vel.y -= 23 * dt; player.pos.y += player.vel.y * dt; }
  let landed = null;
  if (player.vel.y <= 0) {
    for (let i = 0; i < platforms.length; i++) {
      const p = platforms[i];
      if (Math.abs(player.pos.x - p.x) <= p.w / 2 && Math.abs(player.pos.z - p.z) <= p.d / 2 && oldY >= p.y - .04 && player.pos.y <= p.y) {
        landed = { ...p, index: i }; break;
      }
    }
  }
  if (landed) {
    player.pos.y = landed.y; player.vel.y = 0; player.grounded = true;
    if (landed.index > 0 && landed.index < 5) setCheckpoint(landed.index);
  }
  // Walk off an edge naturally; do not treat air as a platform.
  if (player.grounded && !platforms.some(p => Math.abs(player.pos.x - p.x) <= p.w / 2 && Math.abs(player.pos.z - p.z) <= p.d / 2 && Math.abs(player.pos.y - p.y) < .12)) player.grounded = false;
  if (player.pos.y < -10) respawn('WHOOPS — BACK TO YOUR CHECKPOINT');
  if (Math.abs(dx) + Math.abs(dz) > .1) player.group.rotation.y = Math.atan2(dx, -dz);
  player.group.position.copy(player.pos);
  avatarBob += dt * (player.grounded && (Math.abs(dx) + Math.abs(dz) > .1) ? 13 : 3);
  player.group.position.y += player.grounded && (Math.abs(dx) + Math.abs(dz) > .1) ? Math.sin(avatarBob) * .045 : 0;
  player.group.children[4].rotation.x = player.grounded ? Math.sin(avatarBob) * .12 : 0;
  player.group.children[6].rotation.x = player.grounded ? -Math.sin(avatarBob) * .12 : 0;
  const progress = THREE.MathUtils.clamp((12 - player.pos.z) / 43, 0, 1);
  distance = Math.max(distance, Math.round(progress * 100));
  $('#distance').textContent = `${distance} m`; $('#progress-fill').style.width = `${Math.max(8, progress * 100)}%`;
  if (!win && player.pos.z < -29.5 && player.pos.x > -5 && player.pos.x < 5 && player.pos.y > 4) {
    win = true; $('#status-message').textContent = 'BEACON REACHED — YOU MADE IT'; toast('BEACON REACHED — RUN COMPLETE!'); playTone(980, .4);
  }
}
function updateStars(dt) {
  for (const item of stars) {
    if (item.collected) continue;
    item.group.rotation.y += dt * 1.5; item.group.position.y += Math.sin(gameTime * 2 + item.group.position.z) * dt * .13;
    if (player.pos.distanceTo(item.group.position) < 1.25) {
      item.collected = true; item.group.visible = false; player.stars++;
      $('#star-count').textContent = `${player.stars} / ${stars.length} found`;
      document.querySelector('.beacon-chip b').textContent = String(String(stars.length - player.stars).padStart(2, '0'));
      toast(player.stars === stars.length ? 'ALL STARDUST FOUND!' : 'STARDUST +1'); playTone(760 + player.stars * 35, .15);
    }
  }
}
function updateChaser(dt) {
  let target = player.pos, closest = Infinity;
  for (const remote of remotePlayers.values()) {
    const d = remote.group.position.distanceTo(idGroup.position);
    if (d < closest) { closest = d; target = remote.group.position; }
  }
  const delta = new THREE.Vector3(target.x - idGroup.position.x, 0, target.z - idGroup.position.z);
  const d = delta.length();
  if (d > .001) {
    const speed = 3.1 + Math.min(gameTime / 100, 1.2);
    delta.normalize(); idGroup.position.x += delta.x * speed * dt; idGroup.position.z += delta.z * speed * dt;
  }
  idGroup.position.y = THREE.MathUtils.damp(idGroup.position.y, target.y + 1.8 + Math.sin(gameTime * 3) * .25, 3.5, dt);
  idSprite.material.rotation = Math.sin(gameTime * 1.5) * .04;
  idHalo.rotation.z += dt * .65; idHalo.scale.setScalar(1 + Math.sin(gameTime * 3) * .05);
  const playerDistance = idGroup.position.distanceTo(player.pos);
  const danger = playerDistance < 8;
  $('#danger-banner').classList.toggle('show', danger && !caughtTimer);
  if (playerDistance < 1.5 && !caughtTimer && !win) respawn('THE ID GOT YOU — TRY AGAIN');
}
function updateRemotes(dt) {
  for (const remote of remotePlayers.values()) {
    remote.group.position.lerp(remote.target, 1 - Math.exp(-dt * 12));
    remote.group.position.y += Math.sin(gameTime * 5 + remote.target.x) * .008;
  }
}
function updateCamera(dt) {
  const desired = new THREE.Vector3(player.pos.x + 10, player.pos.y + 11, player.pos.z + 15);
  camera.position.lerp(desired, 1 - Math.exp(-dt * 2.5));
  camera.lookAt(player.pos.x, player.pos.y + 1.2, player.pos.z - 4.1);
}
function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), .04); gameTime += dt;
  if (caughtTimer > 0) caughtTimer -= dt;
  updatePlayer(dt); updateStars(dt); updateChaser(dt); updateRemotes(dt); updateCamera(dt);
  goal.rotation.y = Math.sin(gameTime * .6) * .08; beaconTop.rotation.y += dt * .9; beaconRing.rotation.z += dt * .4;
  sendClock += dt;
  if (sendClock > .09) { sendClock = 0; broadcastState(); }
  renderer.render(scene, camera);
}
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
});
// Safe immediate spawn into the main game; no lobby or spawn button is required.
player.pos.set(0, .455, 12); player.checkpoint.copy(player.pos); player.group.position.copy(player.pos);
setRoomUi('SOLO SESSION', 'SKY-01', 'LOCAL');
animate();

