$('#join-btn').addEventListener('click', () => { $('#connect-btn').textContent = 'JOIN WORLD ↗'; $('#connect-btn').dataset.mode = 'join'; $('#join-modal').classList.add('open'); });
$('#modal-close').addEventListener('click', () => $('#join-modal').classList.remove('open'));
